// Remembers what earlier runs already handled (persists once the workflow is active).
const staticData = $getWorkflowStaticData('global');
const seen = new Set(staticData.seenKeys ?? []);
const fresh = $input.all().filter(item => {
  const key = item.json.url;
  return key && !seen.has(key);
});
for (const item of fresh) seen.add(item.json.url);
staticData.seenKeys = [...seen].slice(-2000);
return fresh;

const items = $input.all().map(i => i.json);
const competitor = $('Edit your competitor settings').first().json.competitor;
const corpus = items.slice(0, 40).map(p => {
  const src = p.source_name || p.source || '';
  return `- [${src}] ${(p.title || '')} ${(p.snippet || '')}`.slice(0, 350);
}).join('\n');
const lines = items.slice(0, 12).map(p => {
  const title = (p.title || p.snippet || '').replace(/[<>|]/g, '').slice(0, 120);
  const src = p.source_name || p.source || '';
  return `• <${p.url}|${title}> — ${src}`;
});
return [{ json: { competitor, corpus, lines, count: items.length } }];

